<script lang="ts">import '../app.css';import {onMount} from 'svelte';import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session';let {children}=$props();onMount(()=>{auth.me().then(user=>session.set(user)).catch(()=>{});const handler=()=>{session.set(null);if(location.pathname.startsWith('/dashboard')||location.pathname.startsWith('/wallet')||location.pathname.startsWith('/settings'))goto('/auth/login')};window.addEventListener('regenfeed:unauthorized',handler);return()=>window.removeEventListener('regenfeed:unauthorized',handler)})</script>{@render children()}